import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),l={name:"guide/introduction.md"};function i(n,t,s,d,g,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><h2 id="什么是-galgame-界面插件" tabindex="-1">什么是 Galgame 界面插件？ <a class="header-anchor" href="#什么是-galgame-界面插件" aria-label="Permalink to &quot;什么是 Galgame 界面插件？&quot;">​</a></h2><p>Galgame 界面插件是一个运行在 <a href="https://sillytavern.app/" target="_blank" rel="noreferrer">SillyTavern</a>（酒馆）中的前端脚本，它能将 AI 角色的普通文本输出<strong>自动转换为视觉小说（Galgame）界面</strong>。</p><p>开启插件后，你将获得：</p><ul><li>🎭 <strong>Galgame 对话框</strong> —— 角色名、对话、旁白逐段推进</li><li>🖼️ <strong>动态背景</strong> —— 根据剧情自动切换场景</li><li>💃 <strong>角色立绘 / Live2D</strong> —— 多角色同屏，表情随对话变化</li><li>🔊 <strong>角色语音</strong> —— TTS 自动为角色配音</li><li>✨ <strong>粒子特效</strong> —— 雨雪樱花雾等氛围特效</li><li>🎵 <strong>背景音乐</strong> —— 根据剧情自动搜索播放 BGM</li><li>🗺️ <strong>地图系统</strong> —— 可视化地点标记</li><li>🎨 <strong>多款主题皮肤</strong> —— 一键切换风格</li></ul><h2 id="谁适合使用" tabindex="-1">谁适合使用？ <a class="header-anchor" href="#谁适合使用" aria-label="Permalink to &quot;谁适合使用？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>用途</th></tr></thead><tbody><tr><td><strong>普通用户</strong></td><td>安装插件 → 导入角色卡 → 直接享受 Galgame 体验</td></tr><tr><td><strong>角色卡作者</strong></td><td>为自己的角色卡配置资源并导出，让用户开箱即用 → <a href="/galgame/card-author/overview.html">查看卡作者接入指南</a></td></tr></tbody></table><h2 id="效果展示" tabindex="-1">效果展示 <a class="header-anchor" href="#效果展示" aria-label="Permalink to &quot;效果展示&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">📸 截图和视频即将添加</p><p>此处将放置插件运行效果的截图和演示视频。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>准备好了吗？进入 <a href="/galgame/guide/getting-started.html">快速开始</a> 来安装和使用插件。</p>',11)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
